import java.util.*;

public class Main {
    static String[] sortPeople(String[] names, int[] heights) {
        int n = names.length;
        String[] resultNames = names.clone();
        int[] resultHeights = heights.clone();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n - 1 - i; j++) {
                if (resultHeights[j] < resultHeights[j + 1]) {
                    int th = resultHeights[j]; resultHeights[j] = resultHeights[j + 1]; resultHeights[j + 1] = th;
                    String tn = resultNames[j]; resultNames[j] = resultNames[j + 1]; resultNames[j + 1] = tn;
                }
            }
        }
        return resultNames;
    }

    public static void main(String[] args) {
        System.out.println(Arrays.toString(sortPeople(new String[]{"Mary", "John", "Emma"}, new int[]{180, 165, 170})));
        System.out.println(Arrays.toString(sortPeople(new String[]{"Alice", "Bob", "Bob"}, new int[]{155, 185, 150})));
    }
}

