using namespace std;

vector<string> sortPeople(vector<string>& names, vector<int>& heights) {
    int n = names.size();
    vector<string> resultNames = names;
    vector<int> resultHeights = heights;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n - 1 - i; j++) {
            if (resultHeights[j] < resultHeights[j + 1]) {
                swap(resultHeights[j], resultHeights[j + 1]);
                swap(resultNames[j], resultNames[j + 1]);
            }
        }
    }
    return resultNames;
}

int main() {
    vector<string> names1 = {"Mary", "John", "Emma"};
    vector<int> heights1 = {180, 165, 170};
    for (auto& s : sortPeople(names1, heights1)) cout << s << " ";
    cout << endl;
